import{_ as t,o as n,c as a,a5 as i}from"./chunks/framework.CsGesDJn.js";const u=JSON.parse('{"title":"Plan — View Agency Invitation Status (FR 3.4.8)","description":"","frontmatter":{},"headers":[],"relativePath":"feature/agency-workspace/3-4-8-view-agency-invitation-status/plan.md","filePath":"feature/agency-workspace/3-4-8-view-agency-invitation-status/plan.md"}'),o={name:"feature/agency-workspace/3-4-8-view-agency-invitation-status/plan.md"};function c(s,e,d,l,r,h){return n(),a("div",null,[...e[0]||(e[0]=[i(`<h1 id="plan-—-view-agency-invitation-status-fr-3-4-8" tabindex="-1">Plan — View Agency Invitation Status (FR 3.4.8) <a class="header-anchor" href="#plan-—-view-agency-invitation-status-fr-3-4-8" aria-label="Permalink to &quot;Plan — View Agency Invitation Status (FR 3.4.8)&quot;">​</a></h1><p>&gt; Liên kết: <a href="./spec.html">spec.md</a> — cho Owner xem invitation của Agency, User xem invitation của chính mình; hết hạn 1-30 ngày (mặc định 30, do 3.4.7 set khi tạo invitation).</p><h2 id="_1-pham-vi-ky-thuat" tabindex="-1">1. Phạm vi kỹ thuật <a class="header-anchor" href="#_1-pham-vi-ky-thuat" aria-label="Permalink to &quot;1. Phạm vi kỹ thuật&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Mục</th><th>Nội dung</th></tr></thead><tbody><tr><td>Repo</td><td><code>brandhub-business-service</code></td></tr><tr><td>File implement</td><td><code>AgencyServiceImpl.listInvitations()</code>, <code>listMyPendingInvitations()</code>, <code>acceptInvitation()</code>, <code>declineInvitation()</code></td></tr><tr><td>File đã có</td><td><code>AgencyController</code> (GET <code>/{agencyId}/invitations</code>, GET <code>/invitations/my-pending</code>, POST <code>/invitations/accept</code>, POST <code>/invitations/decline</code>)</td></tr></tbody></table><h2 id="_2-api-contract-final" tabindex="-1">2. API Contract (final) <a class="header-anchor" href="#_2-api-contract-final" aria-label="Permalink to &quot;2. API Contract (final)&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>GET /api/v1/agencies/{agencyId}/invitations      (Owner xem của Agency mình)</span></span>
<span class="line"><span>→ 200 ApiResponse&lt;List&lt;AgencyInvitationResponse&gt;&gt;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>GET /api/v1/agencies/invitations/my-pending      (User xem của chính mình)</span></span>
<span class="line"><span>→ 200 ApiResponse&lt;List&lt;AgencyInvitationResponse&gt;&gt;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>POST /api/v1/agencies/invitations/accept         Body: { &quot;token&quot;: &quot;string&quot; }</span></span>
<span class="line"><span>→ 200 ApiResponse&lt;AgencyMemberResponse&gt;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>POST /api/v1/agencies/invitations/decline        Body: { &quot;token&quot;: &quot;string&quot; }</span></span>
<span class="line"><span>→ 200 ApiResponse&lt;Void&gt;</span></span></code></pre></div><p>Khác so với spec.md (đề xuất <code>GET /api/v1/users/me/invitations</code>):</p><ul><li><strong>Dùng <code>GET /invitations/my-pending</code></strong> thay <code>GET /users/me/invitations</code> — route nằm chung trong <code>AgencyController</code> (không tạo thêm <code>UserController</code> route). Trả <code>agencyName</code> để hiển thị.</li><li><strong>Hết hạn tính tại thời điểm query</strong> (filter <code>expiresAt &gt; now</code>), KHÔNG dùng scheduled job set <code>EXPIRED</code>. Lý do: đơn giản, chính xác hơn, không cần job. Accept/decline cũng check <code>expiresAt</code> trước khi xử lý.</li></ul><h2 id="_3-data-model" tabindex="-1">3. Data Model <a class="header-anchor" href="#_3-data-model" aria-label="Permalink to &quot;3. Data Model&quot;">​</a></h2><ul><li>Đọc <code>agency_invitations</code>, <code>agencies</code> (lấy <code>agencyName</code>), <code>users</code>.</li><li>Accept: ghi <code>agency_members</code> (role <code>MEMBER</code>), cập nhật invitation <code>status = ACCEPTED</code>.</li><li>Decline: <code>status = REVOKED</code> (V2 <code>InvitationStatus</code> không có <code>DECLINED</code>).</li></ul><h2 id="_4-luong-xu-ly" tabindex="-1">4. Luồng xử lý <a class="header-anchor" href="#_4-luong-xu-ly" aria-label="Permalink to &quot;4. Luồng xử lý&quot;">​</a></h2><p><code>acceptInvitation</code>:</p><ol><li>Tìm invitation theo token → 404/<code>INVALID_INVITATION</code>.</li><li>Check <code>status == PENDING</code> và <code>expiresAt</code> chưa qua → nếu sai <code>INVALID_INVITATION</code>.</li><li>Check <code>invitedEmail == user.email</code> (tránh accept nhầm) → <code>INVALID_INVITATION</code>.</li><li>Check chưa là member → <code>ALREADY_AGENCY_MEMBER</code>.</li><li>Save <code>AgencyMember(MEMBER)</code> + set invitation <code>ACCEPTED</code>.</li></ol><h2 id="_5-dependencies" tabindex="-1">5. Dependencies <a class="header-anchor" href="#_5-dependencies" aria-label="Permalink to &quot;5. Dependencies&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Chiều</th><th>Mô tả</th></tr></thead><tbody><tr><td>Chặn bởi</td><td><code>AgencyInvitation</code>, <code>AgencyMember</code> entity (đã có)</td></tr><tr><td>Bị chặn</td><td>luồng mời hoàn chỉnh (3.4.7)</td></tr></tbody></table><h2 id="_6-rui-ro-ky-thuat" tabindex="-1">6. Rủi ro kỹ thuật <a class="header-anchor" href="#_6-rui-ro-ky-thuat" aria-label="Permalink to &quot;6. Rủi ro kỹ thuật&quot;">​</a></h2><ul><li><strong>Accept đúng lúc hết hạn (spec mục 7):</strong> check <code>expiresAt.isBefore(now)</code> ngay trước khi tạo member → chặn, không tạo member với invite hết hạn. Đã xử lý.</li><li><strong><code>DECLINED</code> vs <code>REVOKED</code>:</strong> enum V2 thiếu <code>DECLINED</code>, dùng <code>REVOKED</code> làm terminal state. Ghi chú rõ để BA xác nhận tên.</li></ul>`,17)])])}const g=t(o,[["render",c]]);export{u as __pageData,g as default};
